	public String getNombreEstado() {

		String nombre = "";

		if (FORMULACION.equals(this.aviEstado)) {
			nombre = "Formulación";
		} else if (DEVUELTO.equals(this.aviEstado)) {
			nombre = "Devuelto para correcciones";
		} else if (ENVIADO.equals(this.aviEstado)) {
			nombre = "Enviado";
		} else if (BORRADO.equals(this.aviEstado)) {
			nombre = "Solicitud anulada";
		} else if (REVISADO_UAB.equals(this.aviEstado)) {

			nombre = verificarEstadoUab();

		} else if (REVISADO_FACULTAD.equals(this.aviEstado) && APROBADO.equals(this.aviAvalfacultad)
				&& this.tipo.equals(TIPO_JORNADA_DOCENTE) && this.aviAvalUab == null) {
			nombre = "Aprobado en UAB";
		} else if (REVISADO_FACULTAD.equals(this.aviEstado)) {
			nombre = verificarEstadoFacultad();
		} else if (REVISADO_DIRECCION.equals(this.aviEstado)) {
			nombre = verificarEstadoDireccion();
		}else if (ENVIADO_FACULTAD.equals(this.aviEstado)) {
			nombre = "Enviado a facultad";
		}else if (ENVIADO_SEDE.equals(this.aviEstado)) {
			nombre = "Enviado a la sede";
		}else if (REVISADO_VICERRECTORIA.equals(this.aviEstado)) {
			if (avalVice != null && avalVice.equals(APROBADO)) {
				nombre = "Aprobado en Vicerrectoría";
			} else {
				nombre = "No aprobado en Vicerrectoría";
			}
		} else if (REVISADO_DRE.equals(this.aviEstado)) {
			nombre = verificarEstadoDRE();
		} else if (REVISADO_RECTORIA.equals(this.aviEstado)) {
			nombre = verificarEstadoRectoria();
		} else if (ETICO_ENVIADO_CEPI.equals(this.aviEstado)) {
			nombre = "Enviado a CEPI";
		} else if (ETICO_APROBADO_CEPI.equals(this.aviEstado)) {
			nombre = "Aprobado CEPI";
		} else if (ETICO_NO_APROBADO_CEPI.equals(this.aviEstado)) {
			nombre = "No aprobado CEPI";
		} else if (ETICO_DEVUELTO_CEPI.equals(this.aviEstado)) {
			nombre = "Devuelto para correcciones CEPI";
		} else if (ETICO_ENVIADO_CESI.equals(this.aviEstado)) {
			nombre = "Enviado a CESI";
		} else if (ETICO_APROBADO_CESI.equals(this.aviEstado)) {
			nombre = "Aprobado CESI";
		} else if (ETICO_NO_APROBADO_CESI.equals(this.aviEstado)) {
			nombre = "No aprobado CESI";
		}
		
		return nombre;
	}

	private String verificarEstadoUab() {
		String nombreEstadoUab = "Revisado";
		if (aviAvalUab != null && aviAvalUab.equals(APROBADO) && aviAvalfacultad == null && aviAvaldireccion == null) {
			nombreEstadoUab = "Aprobado en UAB";
		} else if (aviAvalUab != null && aviAvalUab.equals(APROBADO) && aviAvalfacultad != null
				&& aviAvalfacultad.equals(APROBADO)) {
			nombreEstadoUab = "Aprobado en UAB - Asignado coordinador en Vicedecanatura";
		} else if (aviAvalUab != null && aviAvalUab.equals(NEGADO)) {
			nombreEstadoUab = "No aprobado en UAB";
		} else if (aviAvalUab != null && aviAvalUab.equals(APROBADO) && aviAvaldireccion != null
				&& aviAvaldireccion.equals(APROBADO)) {
			nombreEstadoUab = "Aprobado en UAB - Asignado coordinador en Dirección";
		}
		return nombreEstadoUab;
	}

	private String verificarEstadoFacultad() {
		String nombreEstadoFacultad = "";
		if ((this.tipo.equals(TIPO_INVESTIGACION_CONT) && this.getDependenciaContrapartida() != null
				&& "D".equals(this.getDependenciaContrapartida()))
				|| (this.dependencia != null && this.dependencia.getId() != null
						&& (this.getDependencia().getId().startsWith("6")
								|| this.getDependencia().getId().startsWith("7")
								|| this.getDependencia().getId().startsWith("8")))) {
			nombreEstadoFacultad = "Enviado";
		} else {
			if (!this.tipo.equals(TIPO_INVESTIGACION_CONT)) {
				if (aviAvalfacultad != null && aviAvalfacultad.equals(APROBADO)) {
					nombreEstadoFacultad = "Aprobado en Facultad/Instituto";
				} else if (aviAvalfacultad != null && aviAvalfacultad.equals(NEGADO)) {
					nombreEstadoFacultad = "No aprobado en Facultad/Instituto";
				} else {
					nombreEstadoFacultad = "Revisado Facultad/Instituto";
				}
			} else if (this.tipo.equals(TIPO_PERMISO_RECOLECCION) || this.tipo.equals(TIPO_ACCESO_RECURSO)) {

				if (aviAvalfacultad != null && aviAvalfacultad.equals(APROBADO)) {
					nombreEstadoFacultad = "Aprobado por coordinador";
				} else if (aviAvalfacultad != null && aviAvalfacultad.equals(NEGADO)) {
					nombreEstadoFacultad = "No aprobado por coordinador";
				} else {
					nombreEstadoFacultad = "Revisado coordinador";
				}
			}
		}
		return nombreEstadoFacultad;
	}

	private String verificarEstadoDireccion() {

		if (aviAvaldireccion != null && aviAvaldireccion.equals(APROBADO)) {
			return "Aprobado en Dirección";
		} else if (aviAvaldireccion != null && aviAvaldireccion.equals(NEGADO)) {
			return "No aprobado en Dirección";
		} else {
			return "Revisado Dirección";
		}
	}
	
	private String verificarEstadoDRE() {

		if (avalDRE != null && avalDRE.equals(APROBADO)) {
			return "Aprobado en Dirección de Relaciones Exteriores";
		} else if (avalDRE != null && avalDRE.equals(NEGADO)) {
			return "No Aprobado en Dirección de Relaciones Exteriores";
		} else {
			return "Revisado en Dirección de Relaciones Exteriores";
		}
	}
	
	private String verificarEstadoRectoria() {
		if (avalRectoria != null && avalRectoria.equals(APROBADO)) {
			return "Aprobado en Rectoría";
		} else {
			return "";
		}
	}

	public String getNombreTipo() {
		String nombre = "";
		if (this.tipo == null) {
			return "";
		}
		if (this.tipo.equals(TIPO_INVESTIGACION) || "PI".equals(this.tipo) || "IP".equals(this.tipo)) {
			nombre = "Proyecto investigación";
		} else if (this.tipo.equals(TIPO_INVESTIGACION_CONT)) {
			nombre = "Proyecto investigación - Contrapartida";
		} else if (this.tipo.equals(TIPO_JORNADA_DOCENTE)) {
			nombre = "Jornada docente";
		} else if (this.tipo.equals(TIPO_REGALIAS)) {
			nombre = "Regalías";
		} else if (this.tipo.equals(TIPO_GRUPO_INVESTIGACION)) {
			nombre = "Grupo de investigación";
		} else if (this.tipo.equals(TIPO_INVESTIGADOR_INDEPENDIENTE)) {
			nombre = "Investigador independiente o Becas doctorales";
		} else if (this.tipo.equals(TIPO_MOVILIDAD)) {
			nombre = "Movilidad / Evento";
		} else if ("JI".equals(this.tipo)) {
			nombre = "Jóvenes investigadores";
		} else if (this.tipo.equals(TIPO_PERMISO_RECOLECCION)) {
			nombre = "Recolección de especímenes";
		} else if (this.tipo.equals(TIPO_ACCESO_RECURSO)) {
			nombre = "Acceso a recurso genético";
		} else if (this.tipo.equals(TIPO_PAED_REGALIAS)) {
			nombre = "PROYECTO - PAED/ Convocatorias FCTeI - Regalías";
		} else if (this.tipo.equals(TIPO_CENTRO_INVESTIGACION)) {
			nombre = "Laboratorios, centros o Institutos de Investigación";
		} else if (this.tipo.equals(TIPO_ETICO)) {
			nombre = "Aval ético para proyecto";
		} else if (this.tipo.equals(TIPO_ARTICULO_INVESTIGACION)) {
			nombre = "Artículo de investigación";
		} else if (this.tipo.equals(TIPO_CONVOCATORIA_REGALIAS)) {
			nombre = "Aval etapa presentación proyectos Convocatorias SGR- Regalías";
		} else if (this.tipo.equals(TIPO_REGALIAS_VERIF_REQ)) {
			nombre = "Aval etapa verificación de requisitos SGR - Regalías";
		}
		return nombre;
	}

	public boolean isEsRequiereTerminos() {
		if (!isEsJornadaDocente() && !isEsProyectoContrapartida()) {
			return true;
		}
		return false;
	}

