	@Override
	public boolean equals(Object obj) {
		if (this == obj)
			return true;
		if (obj == null)
			return false;
		if (getClass() != obj.getClass())
			return false;
		Aval other = (Aval) obj;
		if (aviId == null) {
			if (other.aviId != null)
				return false;
		} else if (!aviId.equals(other.aviId))
			return false;
		return true;
	}

