	public boolean isEsAvalAprobadoParaLegalizacion() {
		return (StringUtils.isNotBlank(this.getAviEstado()) && StringUtils.isNotBlank(this.getAviAvaldireccion())
				&& ((this.getAviEstado().equals(Aval.REVISADO_DIRECCION)
						&& this.getAviAvaldireccion().equals(Aval.APROBADO))
				|| (this.getAviEstado().equals(Aval.REVISADO_VICERRECTORIA)
						&& this.getAviAvaldireccion().equals(Aval.APROBADO))
				|| (this.getAviEstado().equals(Aval.REVISADO_DRE) && this.getAvalDRE().equals(Aval.APROBADO))
				|| (this.getAviEstado().equals(Aval.REVISADO_RECTORIA) && this.getAvalRectoria().equals(Aval.APROBADO))));
	}
	

